CREATE DATABASE IF NOT EXISTS fiz_smart_waste_bank CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fiz_smart_waste_bank;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('member','admin') NOT NULL DEFAULT 'member',points BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rfid_cards(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,uid VARCHAR(64) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS qr_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,code VARCHAR(128) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS waste_types(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,points_per_kg INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE);
INSERT IGNORE INTO waste_types(code,name,points_per_kg) VALUES('plastic','Plastik',100),('paper','Kertas',80),('metal','Logam',150),('glass','Kaca',60),('organic','Organik',30);
CREATE TABLE IF NOT EXISTS transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(120) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,device_id VARCHAR(80) NOT NULL,waste_type_id BIGINT UNSIGNED NOT NULL,weight_kg DECIMAL(10,3) NOT NULL,points_earned BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(waste_type_id) REFERENCES waste_types(id),INDEX idx_user_created(user_id,created_at));
